extra_css:
/* theme: risograph-paper (2026-10-27) */
:root,:root:not(x){--bg:#f6eedb;--fg:#3a2416;--muted:#6f5442;--line:#dccaa6;--card:#fffaf0;--soft:#efe2c4;--accent:#b8321c;--accent2:#d4920f}
@media (prefers-color-scheme:dark){:root{--bg:#f6eedb;--fg:#3a2416;--muted:#6f5442;--line:#dccaa6;--card:#fffaf0;--soft:#efe2c4;--accent:#b8321c;--accent2:#d4920f}}
body{font-family:"Zen Kaku Gothic New","Hiragino Sans",sans-serif;background-image:radial-gradient(#3a241612 1px,transparent 1.2px);background-size:6px 6px}
header{background:#fffaf0;border-bottom:3px solid #3a2416}
.logo,.hero h1,article h1,.sec-h,article h2,.picks-h,.next-h{font-family:"Dela Gothic One","Hiragino Sans",sans-serif;font-weight:400;letter-spacing:.02em}
.logo{color:#3a2416}.logo span{color:#b8321c}
.gnav a{background:#fffaf0;border:2px solid #3a2416;border-radius:6px;color:#3a2416}
.gnav a:hover,.gnav a.on{background:#d4920f;color:#3a2416;box-shadow:3px 3px 0 #3a2416}
.hero-img{border:3px solid #3a2416;border-radius:6px;box-shadow:6px 6px 0 #b8321c}
.sec-h{border-bottom:4px solid #3a2416;color:#b8321c}
.card{border:2px solid #3a2416;border-radius:6px;box-shadow:4px 4px 0 #d4920f}
.thumb{border-radius:4px 4px 0 0;border-bottom:2px solid #3a2416}
.card:hover{border-color:#3a2416;box-shadow:6px 6px 0 #b8321c}
.tag{background:#b8321c;border-radius:4px}
article h2{background:#3a2416;color:#fff3dc;border-left:0;border-radius:4px;box-shadow:5px 5px 0 #d4920f}
article h3{border-bottom:3px solid #d4920f}
.eyecatch{border:3px solid #3a2416;border-radius:6px}
.lead,.toc,.shop,aside .box,.author{border:2px solid #3a2416;border-radius:6px}
.toc{border-top:6px solid #b8321c}
.note{border-left:6px solid #d4920f;border-radius:4px}
.picks{border:3px solid #3a2416;border-radius:6px;box-shadow:5px 5px 0 #b8321c}
.picks-h{color:#b8321c}
.next{border:2px dashed #3a2416;background:#efe2c4;border-radius:6px}.next-h{color:#b8321c}
.avatar{background:#d4920f;color:#3a2416;border-radius:6px}
aside .box-h{border-bottom:3px solid #3a2416}
.mini img{border-radius:3px}.mini b{background:#b8321c;border-radius:4px}
th{background:#efe2c4}th,td{border-color:#cbb48b}
code{background:#fff3dc}
footer{background:#3a2416;color:#e9d8b8;border-top:0}footer a{color:#ffd27a}

/* hero-base: 2026-10-27 トップの見せ場の共通部分 */
.hx{padding:24px 0 6px}.hx-eyebrow{font-size:13px;font-weight:700;letter-spacing:.08em;color:var(--accent);margin:0 0 8px}
.hx-h1{font-size:clamp(28px,5vw,46px);line-height:1.3;margin:0 0 14px}.hx-h1 em{font-style:normal;color:var(--accent)}
.hx-lead{color:var(--muted);font-size:15px;margin:0 0 22px;max-width:680px}
.hx-chips{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0 26px}.hx-chips a{text-decoration:none;font-size:13px;padding:5px 12px}
.hx-vs{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;margin:0 0 22px}.hx-vs p{margin:0;font-size:13px;color:var(--muted)}
.hx-k{font-size:12px;color:var(--muted)}.hx-v{font-size:clamp(20px,3.4vw,28px);font-weight:800;line-height:1.35;margin:4px 0}
.hx-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 22px}.hx-stats b{display:block;line-height:1.1;font-variant-numeric:tabular-nums}.hx-stats span{font-size:12px;color:var(--muted)}
.hx-steps{list-style:none;padding:0;margin:0 0 8px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.hx-steps strong{display:block;font-size:15px}.hx-steps span{font-size:12px;color:var(--muted)}
@media (max-width:560px){.hx-vs,.hx-steps{grid-template-columns:1fr}.hx-stats{gap:6px}.hx-mid{justify-self:center}.hx-vs{text-align:center}}
[data-seq]>*{opacity:0;transform:translateY(6px);transition:opacity .4s,transform .4s}[data-seq]>.on{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-seq]>*{opacity:1;transform:none;transition:none}}

/* hero: recipe-card (2026-10-27) */
.hx-riso-top{display:grid;grid-template-columns:1.1fr 1fr;gap:26px;align-items:center}
.hx-riso .hx-h1{font-family:"Dela Gothic One",sans-serif;font-weight:400;color:#3a2416;font-size:clamp(26px,3.4vw,36px)}.hx-riso .hx-h1 em{color:#b8321c}
.hx-recipe{position:relative;background:#fffaf0 repeating-linear-gradient(transparent 0 31px,#e8d7b4 31px 32px);border:3px solid #3a2416;padding:22px 20px 14px;box-shadow:8px 8px 0 #b8321c;transform:rotate(-1.2deg)}
.hx-rc-tape{position:absolute;top:-14px;left:50%;width:110px;height:26px;margin-left:-55px;background:#d4920fcc;transform:rotate(2deg)}
.hx-rc-h{font-family:"Dela Gothic One",sans-serif;font-size:19px;color:#b8321c}.hx-rc-h small{display:block;font-family:inherit;font-size:12px;color:#6f5442}
.hx-rc{margin:10px 0}.hx-rc div{display:flex;justify-content:space-between;border-bottom:2px dotted #3a2416;padding:4px 0;font-weight:700}.hx-rc dd{margin:0;color:#b8321c}
.hx-rc-foot{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:12px;color:#6f5442}
.hx-go{background:#3a2416;color:#fff3dc;text-decoration:none;font-weight:700;font-size:13px;padding:7px 14px;border-radius:4px;box-shadow:3px 3px 0 #d4920f}
.hx-riso .hx-chips a{background:#fffaf0;border:2px solid #3a2416;color:#3a2416;border-radius:4px;font-weight:700}.hx-riso .hx-chips a:hover{background:#d4920f}
.hx-riso .hx-vs{background:#fffaf0;border:3px solid #3a2416;padding:18px 14px;text-align:center}
.hx-riso .hx-side.on{background:#d4920f33;padding:8px}.hx-riso .hx-side.on .hx-v{color:#b8321c}.hx-riso .hx-v{font-family:"Dela Gothic One",sans-serif;font-weight:400}
.hx-riso .hx-mid{font-family:"Dela Gothic One",sans-serif;font-size:20px;color:#fff3dc;background:#b8321c;border-radius:50%;width:44px;height:44px;line-height:44px;text-align:center}
.hx-riso .hx-stats div{text-align:center}
.hx-riso .hx-stats b{width:96px;height:96px;margin:0 auto 6px;border:4px double #b8321c;border-radius:50%;display:flex;align-items:center;justify-content:center;font-family:"Dela Gothic One",sans-serif;font-size:38px;color:#b8321c;transform:rotate(-8deg);background:#fffaf0}
.hx-riso .hx-stats div:nth-child(2) b{transform:rotate(5deg);border-color:#3a2416;color:#3a2416}.hx-riso .hx-stats div:nth-child(3) b{transform:rotate(-3deg);border-color:#d4920f;color:#9a6a08}
.hx-riso .hx-steps li{background:#fffaf0;border:2px solid #3a2416;padding:12px;display:grid;grid-template-columns:auto 1fr;column-gap:10px}
.hx-riso .hx-steps b{grid-row:span 2;width:40px;height:40px;border-radius:50%;background:#b8321c;color:#fff3dc;font-family:"Dela Gothic One",sans-serif;font-weight:400;font-size:20px;display:flex;align-items:center;justify-content:center;box-shadow:3px 3px 0 #3a2416}
@media (max-width:760px){.hx-riso-top{grid-template-columns:1fr}.hx-recipe{transform:none}}
